Voici un exemple de code en C# qui illustre l'utilisation des collections génériques, en particulier la classe `List<T>` :

```csharp
using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // Création d'une liste générique de chaînes de caractères
        List<string> noms = new List<string>();

        // Ajout d'éléments à la liste
        noms.Add("Alice");
        noms.Add("Bob");
        noms.Add("Charlie");

        // Accès aux éléments de la liste
        Console.WriteLine("Liste des noms :");
        foreach (string nom in noms)
        {
            Console.WriteLine(nom);
        }

        // Utilisation d'une autre collection générique : Dictionary<TKey, TValue>
        Dictionary<int, string> dictionnaire = new Dictionary<int, string>();
        dictionnaire.Add(1, "Un");
        dictionnaire.Add(2, "Deux");
        dictionnaire.Add(3, "Trois");

        Console.WriteLine("\nContenu du dictionnaire :");
        foreach (KeyValuePair<int, string> paire in dictionnaire)
        {
            Console.WriteLine($"{paire.Key}: {paire.Value}");
        }

        // Utilisation d'une collection générique avec une classe personnalisée
        List<Personne> personnes = new List<Personne>();
        personnes.Add(new Personne("Alice", 30));
        personnes.Add(new Personne("Bob", 25));

        Console.WriteLine("\nListe des personnes :");
        foreach (Personne personne in personnes)
        {
            Console.WriteLine($"{personne.Nom} a {personne.Age} ans");
        }
    }
}

// Classe personnalisée pour illustrer l'utilisation avec des types génériques
class Personne
{
    public string Nom { get; }
    public int Age { get; }

    public Personne(string nom, int age)
    {
        Nom = nom;
        Age = age;
    }
}
```

Ce code montre :
1. L'utilisation d'une `List<string>` pour stocker des chaînes de caractères
2. L'utilisation d'un `Dictionary<int, string>` pour stocker des paires clé-valeur
3. L'utilisation d'une `List<Personne>` avec une classe personnalisée

Les collections génériques en C# permettent de créer des collections fortement typées, ce qui améliore la sécurité des types et réduit les erreurs de conversion.
